import os
import re
import json
from taf.ul.sc.unix_functionality import UnixFunctionality  # type: ignore
from moler.exceptions import CommandFailure  # type: ignore
from taf.ul.sc.perf.exceptions import FileNotFoundError


class BTSStats(object):

    def __init__(self, log_dir):
        self.log_dir = log_dir
        self.unix_local = UnixFunctionality(device_name="UnixLocal", autoconnect=True)

    def get_all_results_file_locations(self, json_file):
        results_file_locations = []

        any_device = "*"
        pmstats_location_regex = os.path.join(self.log_dir, "report", any_device, 'pmstats', json_file)

        try:
            ls_output = self.unix_local.ls(options="-d {}".format(pmstats_location_regex))
            results_file_locations = ls_output['files'].keys()

        except (CommandFailure, KeyError) as error:
            raise FileNotFoundError("{} file is not available - {}".format(json_file, error))

        return results_file_locations

    @staticmethod
    def get_device_name_from_pmstats_path(pmstats_path):
        path_regex = re.compile(r'report/(?P<DEVICE_NAME>.*?)/pmstats')
        match = path_regex.search(pmstats_path)
        if match:
            return match.group('DEVICE_NAME')

    @staticmethod
    def load_stats_file(path_to_json_file):
        with open(path_to_json_file) as json_file:
            data = json.load(json_file)
        return data
